def recycle_status(candidate):
 receipt_path=ROOT/'local-data/维护清理/回收/统一库清单-261103-001/回执.json'
 if not receipt_path.exists():return None
 receipt=read(receipt_path)
 if receipt['status'] not in ('完成','已清除'):return None
 assert receipt['approved_sha256']==sha(HOME/'待删除/删除候选精确清单.json')
 other=read(ROOT/receipt['other_receipt']);assert other['status'] in ('完成','已清除');approved={r['relative_path']:r for r in candidate['files']};locations={}
 for label,data in [('本批七天回收',receipt),('并行批准批次已回收',other)]:
  for r in data['files']:
   if r['state'] not in ('stored','purged') or r['path'] not in approved:continue
   original=approved[r['path']];assert r['sha256']==original['sha256'] and r['bytes']==original['bytes'];assert r['path'] not in locations
   locations[r['path']]={**r,'result':'已永久清除' if r['state']=='purged' else label}
 delayed=[r for r in candidate['files'] if r['relative_path'] not in locations]
 assert len(locations)==10910 and len(delayed)==1 and delayed[0]['relative_path']=='local-data/资源归档/全库第一版/原始资源固实归档.7z'
 deadline=max(r['moved_at'] for r in locations.values())+7*86400
 result={'approved_count':candidate['count'],'approved_bytes':candidate['bytes'],'approved_sha256':receipt['approved_sha256'],
         'this_batch_files':receipt['moved_files'],'this_batch_bytes':receipt['moved_bytes'],'other_batch_files':other['moved_files'],'other_batch_bytes':other['moved_bytes'],
         'recycled_files':len(locations),'recycled_bytes':sum(r['bytes'] for r in locations.values()),'protected_files':len(delayed),'protected_bytes':sum(r['bytes'] for r in delayed),
         'protected':[{'path':r['relative_path'],'bytes':r['bytes']} for r in delayed],
         'permanently_deleted':sum(r['state']=='purged' for r in locations.values()),
         'permanently_deleted_bytes':sum(r['bytes'] for r in locations.values() if r['state']=='purged'),
         'currently_recycled_files':sum(r['state']=='stored' for r in locations.values()),
         'automatic_purge':False,'purge_not_before':deadline,
         'earliest_review_local':datetime.fromtimestamp(deadline,ZoneInfo('America/Los_Angeles')).isoformat(),
         'receipt':receipt_path.relative_to(ROOT).as_posix(),'other_receipt':receipt['other_receipt']}
 save(HOME/'验收/清理执行汇总.json',result)
 with (HOME/'验收/七天回收逐文件结果.csv').open('w',encoding='utf-8-sig',newline='') as stream:
  writer=csv.writer(stream);writer.writerow(['原完整路径','字节','SHA256','处理结果','回收位置','移动时间UTC'])
  for r in candidate['files']:
   state=locations.get(r['relative_path'],{});writer.writerow([r['path'],r['bytes'],r['sha256'],state.get('result','保护保留未移动'),str(ROOT/state['stored']) if state else '',datetime.fromtimestamp(state['moved_at'],timezone.utc).isoformat() if state else ''])
 return result

