 defaults=[next(v for v in r['variants'] if v['sha256']==r['default']) for r in registry.values() if r['kind']=='model'];profile_count=sum(len(r['variants']) for r in registry.values() if r['kind']=='model');e=html.escape;gb=lambda n:f'{n/1e9:.2f} GB';mb=lambda n:f'{n/1e6:.2f} MB'
